//const float TEMPERATURE = 0.0; // Absolute zero
const float TEMPERATURE = 0.45; // Supercritical not perfect (best visual result)
//const float TEMPERATURE = 0.5; // Curie temperature (Perfect supercritical value)
//const float TEMPERATURE = 1.0; // Planck temperature

const vec3 COLOR_SPINE_UP = vec3(1.0, 1.0, 1.0);
const vec3 COLOR_SPINE_DOWN = vec3(0.0, 0.0, 0.0);

vec4 cell(in ivec2 p){
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p + r) % r;
    return texelFetch(iChannel0, p, 0 );
}

float hash11(uint n) 
{
    // integer hash copied from Hugo Elias
	n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return float( n & uint(0x7fffffffU))/float(0x7fffffff);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 p = ivec2(fragCoord);

    float spin = -4.5; // -9/2
    spin += cell(p + ivec2(-1, -1)).w;
    spin += cell(p + ivec2(0, -1)).w;
    spin += cell(p + ivec2(1, -1)).w;
    spin += cell(p + ivec2(-1, 0)).w;
    spin += cell(p).w;
    spin += cell(p + ivec2(1, 0)).w;
    spin += cell(p + ivec2(-1, 1)).w;
    spin += cell(p + ivec2(0, 1)).w;
    spin += cell(p + ivec2(1, 1)).w;

    float t = TEMPERATURE;
    if (bool(iMouse.zw)){
        t = iMouse.y / iResolution.y;
    }

    uint n = uint(p.x) + 1920U * uint(p.y) + (1920U * 1080U) * uint(iFrame);
    spin *= hash11(n) / 0.5 < t ? -1.0 : 1.0;

	fragColor = spin > 0.0 ? vec4(COLOR_SPINE_UP.xyz, 1.0) : vec4(COLOR_SPINE_DOWN.xyz, 0.0);
}
